#!/bin/bash
# Reprise : termine apply-docs-recadrage.sh (interrompu avant son commit), puis applique la partie
# « L’éditeur de texte riche » (contenu de apply-docs-editeur.sh). Chaque étape déjà commitée est sautée.
# Usage (racine du repo) : bash apply-docs-reprise.sh
set -u
[ -f package.json ] && [ -d apps/web/content/docs/dev ] || { echo "❌ lancer à la racine du repo"; exit 1; }
git log --format=%s -n 30 | grep -qF "Doc : parties et chapitres numérotés" || { echo "❌ apply-docs-numerotation.sh n’est pas commité : le relancer d’abord"; exit 1; }
ALLOWED="apps/web/content/docs/dev/contenu/reglages-du-site.mdx apps/web/content/docs/dev/editeur/un-modele-adopte-puis-taille.mdx apps/web/content/docs/dev/editeur/une-image-de-la-bibliotheque.mdx apps/web/content/docs/dev/envois/un-fichier-un-usage.mdx apps/web/content/docs/dev/index.mdx apps/web/content/docs/dev/recadrage/sortir-le-bon-fichier.mdx apps/web/content/docs/dev/recadrage/un-etabli-carre.mdx apps/web/src/features/docs/entities/procedureMap.generated.json apps/web/src/features/docs/lib/docs.navigation.ts"
# Les scripts applicateurs posés à la racine (apply-*.sh…) ne comptent pas : ils ne sont jamais commités par ce script.
OTHER=$(git status --porcelain | grep -v "^??" | cut -c4- | grep -vE '^[^/]+\.sh$' | while read f; do case " $ALLOWED " in *" $f "*) ;; *) echo "$f";; esac; done)
[ -z "$OTHER" ] || { echo "❌ d’autres fichiers suivis sont modifiés, je ne touche à rien :"; echo "$OTHER" | head -5; exit 1; }
check() {
  node scripts/build-procedure-map.mjs --write >/dev/null 2>&1 || { echo "❌ carte des procédures : échec"; return 1; }
  if pgrep -f "next dev" >/dev/null 2>&1; then
    CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && node scripts/check-doc-entities.mjs && node scripts/check-doc-snippets.mjs && pnpm typecheck && pnpm lint"
  else CHECK="pnpm check"; fi
  if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
    echo "❌ check ÉCHOUÉ (rien n’est commité) :"
    grep -nE "error TS|✗ |ERR_|Error:" /tmp/akfc_tc.log | head -12; grep -v "^[[:space:]]*$" /tmp/akfc_tc.log | tail -8; return 1
  fi
  echo "  ✅ check OK"
}
echo "== étape 1 : docs23: le recadrage"
if git log --format=%s -n 30 | grep -qxF "docs23: le recadrage"; then echo "  déjà commitée : sautée"; else
  mkdir -p "$(dirname "apps/web/content/docs/dev/recadrage/un-etabli-carre.mdx")"; base64 -d > "apps/web/content/docs/dev/recadrage/un-etabli-carre.mdx" <<'B64'

B64
  mkdir -p "$(dirname "apps/web/content/docs/dev/recadrage/sortir-le-bon-fichier.mdx")"; base64 -d > "apps/web/content/docs/dev/recadrage/sortir-le-bon-fichier.mdx" <<'B64'

B64
  mkdir -p "$(dirname "apps/web/content/docs/dev/envois/un-fichier-un-usage.mdx")"; base64 -d > "apps/web/content/docs/dev/envois/un-fichier-un-usage.mdx" <<'B64'

B64
  if git log --format=%s -n 30 | grep -qxF "docs24: l'éditeur de texte riche"; then :; else
  mkdir -p "$(dirname "apps/web/content/docs/dev/index.mdx")"; base64 -d > "apps/web/content/docs/dev/index.mdx" <<'B64'

B64
  fi
  check || exit 1
  git add -- apps/web/content/docs/dev/recadrage/un-etabli-carre.mdx apps/web/content/docs/dev/recadrage/sortir-le-bon-fichier.mdx apps/web/content/docs/dev/envois/un-fichier-un-usage.mdx apps/web/content/docs/dev/index.mdx apps/web/src/features/docs/entities/procedureMap.generated.json
  git commit -q -F - <<'MSG' && echo "  ✅ commit $(git rev-parse --short HEAD)" || { echo "  commit KO"; exit 1; }
