if git log --format=%s -n 30 | grep -qxF "docs24: l'éditeur de texte riche"; then echo "  déjà commitée : sautée"; else
  mkdir -p "$(dirname "apps/web/content/docs/dev/editeur/un-modele-adopte-puis-taille.mdx")"; base64 -d > "apps/web/content/docs/dev/editeur/un-modele-adopte-puis-taille.mdx" <<'B64'

B64
  mkdir -p "$(dirname "apps/web/content/docs/dev/editeur/une-image-de-la-bibliotheque.mdx")"; base64 -d > "apps/web/content/docs/dev/editeur/une-image-de-la-bibliotheque.mdx" <<'B64'

B64
  mkdir -p "$(dirname "apps/web/content/docs/dev/contenu/reglages-du-site.mdx")"; base64 -d > "apps/web/content/docs/dev/contenu/reglages-du-site.mdx" <<'B64'

B64
  mkdir -p "$(dirname "apps/web/content/docs/dev/index.mdx")"; base64 -d > "apps/web/content/docs/dev/index.mdx" <<'B64'

B64
  mkdir -p "$(dirname "apps/web/src/features/docs/lib/docs.navigation.ts")"; base64 -d > "apps/web/src/features/docs/lib/docs.navigation.ts" <<'B64'

B64
  check || exit 1
  git add -- apps/web/content/docs/dev/editeur/un-modele-adopte-puis-taille.mdx apps/web/content/docs/dev/editeur/une-image-de-la-bibliotheque.mdx apps/web/content/docs/dev/contenu/reglages-du-site.mdx apps/web/content/docs/dev/index.mdx apps/web/src/features/docs/lib/docs.navigation.ts apps/web/src/features/docs/entities/procedureMap.generated.json
